/**
 * Jinx Al-Hadikhia + Scarlet Woman: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Al-Hadikhia
 * Wiki: https://wiki.bloodontheclocktower.com/Scarlet_Woman
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { secondDemonReverts } from '#lib/core/rules/jinxes/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';
import { reminderTargetMisses } from '#lib/core/rules/reminders/reminder-targets.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Al-Hadikhia + Scarlet Woman jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alhadikhia', 'scarletwoman');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alhadikhia')?.name).toBe('Al-Hadikhia');
		expect(data.byId.get('scarletwoman')?.name).toBe('Scarlet Woman');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alhadikhia', 'scarletwoman'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alhadikhia'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['scarletwoman'])).not.toContain(jinx);
	});

	describe('the Scarlet Woman becomes the Scarlet Woman again beside a second Demon', () => {
		const ids = ['alhadikhia', 'scarletwoman', 'chef', 'empath', 'monk', 'soldier'];
		const isTheDemon = { characterId: 'scarletwoman', label: 'Is The Demon' };
		// The Al-Hadikhia died and the Scarlet Woman became the Demon.
		const became = scenario(ids, { script: scriptOf(ids) })
			.execute('alhadikhia')
			.reminder('scarletwoman', 'scarletwoman', 'Is The Demon');
		// Then a chosen dead Al-Hadikhia chose to live.
		const back = became.do((at) => ({
			type: 'SetDead',
			seatId: at.seat('alhadikhia'),
			dead: false
		}));

		it("is data in the Scarlet Woman's rules", () => {
			// Wiki: "If there would be two Demons, one of which was the Scarlet Woman, the Scarlet Woman becomes the Scarlet Woman again."
			expect(ownJinxRules(became.game, 'scarletwoman', 'alhadikhia', became.characters)).toEqual({
				notSecondDemon: {}
			});
		});

		it('keeps her the Demon while the Al-Hadikhia stays dead', () => {
			// Wiki: "If there would be two Demons"
			expect(secondDemonReverts(became.game, became.characters)).toEqual([]);
		});

		it('makes her the Scarlet Woman again once the Al-Hadikhia lives', () => {
			// Wiki: "the Scarlet Woman becomes the Scarlet Woman again."
			expect(secondDemonReverts(back.game, back.characters)).toEqual([
				{ seatId: back.seat('scarletwoman'), owner: 'scarletwoman', partner: 'alhadikhia' }
			]);
			expect(
				nightStepAlerts(back.game, 'alhadikhia', back.characters).filter(
					(a) => a.kind === 'reverts'
				)
			).toMatchObject([{ seatId: back.seat('scarletwoman'), partner: 'alhadikhia' }]);
		});

		it('no longer fits her Is The Demon while the Al-Hadikhia lives', () => {
			// Wiki: "the Scarlet Woman becomes the Scarlet Woman again."
			const sw = back.seat('scarletwoman');
			expect(reminderTargetMisses(back.game, isTheDemon, sw, back.characters)).toContain('jinx');
			expect(reminderTargetMisses(became.game, isTheDemon, sw, became.characters)).not.toContain(
				'jinx'
			);
		});
	});
});
